import com.nova.godzillagotchi.*;import java.awt.*;import java.awt.image.*;import java.io.*;import javax.imageio.*;
public class LandmarkTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception{
  SoundCues cues=new SoundCues();cues.start("pickup",2000);check(cues.poll("pickup",2000,1000,true)==SoundCues.SPLATTER,"poop gets splatter, never bubbles");check(cues.poll("pickup",2000,1100,true)==-1,"pickup plays once");cues.start("bath",2800);check(cues.poll("bath",2800,1000,true)==SoundCues.BUBBLES,"bath keeps bubbles");
  Rampage legacy=new Rampage(2);legacy.building=4;legacy.hp=190;Landmarks.migrate(legacy,false);check(legacy.landmark==0&&legacy.building==0&&legacy.hp==150&&!legacy.won(),"old active city keeps one remaining tower");legacy.finished=true;legacy.building=8;Landmarks.migrate(legacy,false);check(legacy.won(),"old completed city remains completed");
  for(int type=0;type<Landmarks.NAMES.length;type++){Rampage r=new Rampage(0,type);r.tick(0);r.nextSpawn=999999;long t=0;int hits=0;while(!r.finished&&t<120000){if(r.canAttack(0)){r.attack(0);hits++;}t+=100;r.tick(t);}check(r.won()&&r.building==1&&r.hp==0&&hits>1,"one multi-hit target per outing");r.tick(t+10000);check(!r.canAttack(0)&&r.building==1,"no second target or attacks after finish");Pet p=new Pet(0);check(r.claimReward(p)&&!r.claimReward(p)&&p.xp==20,"one reward");check(r.landmark==type,"selected landmark stays fixed");}
  int[] palette={0x00ffffff,0xffffffff,0xff20271c};LcdPalette.apply(palette);check(palette[0]>>>24==0&&palette[1]==ThemePainter.LCD_BG&&palette[2]==ThemePainter.LCD_INK,"LCD ink/substrate and alpha");
  SkinPreview preview=new SkinPreview("res/drawable-nodpi");BufferedImage sheet=new BufferedImage(1440,960,BufferedImage.TYPE_INT_RGB);Graphics2D g=sheet.createGraphics();
  for(int theme=0;theme<4;theme++)for(int type=1;type<=6;type++){float[] q=LandmarkAssets.BOUNDS[theme][type-1];check(q[0]>=0&&q[1]>=0&&q[2]>0&&q[3]>0&&q[0]+q[2]<=1.001&&q[1]+q[3]<=1.001,"valid atlas bounds");SkinRenderer.State s=new SkinRenderer.State();s.pet=new Pet(0);s.pet.hatched=true;s.city=new City();s.theme=theme;s.rampage=new Rampage(0,type);s.rampage.tick(0);check(LandmarkRenderer.hit(s.rampage,theme,527,415)&&!LandmarkRenderer.hit(s.rampage,theme,400,160),"target touch geometry");g.drawImage(preview.frame(s,240),(type-1)*240,theme*240,null);for(int hp:new int[]{100,50,0}){s.rampage.hp=hp;s.rampage.hitAt=0;s.rampage.time=hp==0?650:200;preview.frame(s,240);}}
  g.dispose();ImageIO.write(sheet,"png",new File("../Godzillagotchi-3.5-landmarks.png"));System.out.println("PASS: splatter versus bath cues; one-building completion for seven targets; legacy migration; LCD palette; all landmark themes and damage/collapse renders");
 }
}
